\label{def: timelike sectional curvature bound}
A spacetime $(\mathcal M,\mathsf g)$ is said to have a \textit{timelike sectional curvature bound} from below (resp.\ above) by a constant $k \in \mathbb R$ if for all $p \in \mathcal M$ and all timelike planes $\Pi \subseteq T_p\mathcal M$, we have
\begin{equation}
    K(\Pi) \geq k \quad (\text{resp.\ } \leq).
\end{equation}

\begin{enumerate} \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[] 
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} If $\Pi$ is a timelike plane spanned by orthonormal vectors $v,w$ with $v$ unit timelike (i.e., $\mathsf g(v,v) = +1$) and $w$ unit spacelike (i.e., $\mathsf g(w,w) = -1$), then the sectional curvature of $\Pi$ reduces to
    \begin{align}
        K(\Pi) = -\mathsf g(\operatorname{Riem}(w,v)v,w).
    \end{align}
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} If the timelike sectional curvature of $(\mathcal M,\mathsf g)$ is bounded from below (resp.\ above) by $k \in \mathbb R$, then its timelike Ricci curvature is bounded from below (resp.\ above) by $(n-1)k\mathsf g$: Indeed, suppose for simplicity that the bound is from below by $k$ and that $v \in T_p \mathcal M$ is unit timelike, and complete $\{ v \}$ to a basis of $T_p \mathcal M$ by appending unit spacelike vectors $e_2,\dots,e_n$ ($e_1:=v$). Noting that $-\mathsf g(\operatorname{Riem}(e_i,v)v,e_i) \geq k$ for every $i=2,\dots,n$, we get
    \begin{equation}
        \operatorname{Ric}(v,v) = \sum_{i=2}^n g(e_i,e_i) \mathsf g(\operatorname{Riem}(e_i,v)v,e_i) = -\sum_{i=2}^n \mathsf g(\operatorname{Riem}(e_i,v)v,e_i) \geq (n-1)k.
    \end{equation}
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} Note that, due to our choice of signature $(+,-,\dots,-)$ of the Lorentzian metric $\mathsf g$, it is easy to see that our definition of sectional curvature is precisely the negative of the ones often considered in Lorentzian geometry, where the signature is $(-,+,\dots,+)$, e.g. \cite{BKOR24}. Hence, note that timelike sectional curvature bounds from below (resp.\ above) by $k \in \mathbb R$ in our sense correspond to bounds by $-k$ from above (resp.\ below) in the sense of \cite{BKOR24}. While in principle the role of the constant curvature spaces also switches for us (i.e., anti-de Sitter space has positive timelike sectional curvature and de-Sitter space negative), the comparison of various geometric configurations with constant curvature spaces remains the same as outlined in \cite{BKOR24} keeping in mind the passage of the bounds from our conventions to those of \cite{BKOR24}, as discussed above.

    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} Definition \ref{def: timelike sectional curvature bound} is the correct notion of sectional curvature bound in the Lorentzian setting. Indeed, if one were to require the same curvature bound for all $2$-planes in the tangent spaces, 
    as is done in the Riemannian setting, it is well known that the spacetime then would have constant sectional curvature if $n \geq 3$, see Kulkarni \cite{Kulkarni}. 
\end{enumerate}

\label{thm: triangle comparison}
Let $(\mathcal M,\mathsf g)$ be a globally hyperbolic spacetime with timelike sectional curvature bounded below by $- \delta \leq 0$. Given any timelike triangle $\Delta(p_1,p_2,p_3)$ in $M$, i.e.\ any choice of timelike related points $p_1 \ll p_2 \ll p_3$ as well as a choice of connecting timelike maximizers from $p_1$ to $p_3$ and from $p_1$ to $p_2$, and a not necessarily maximizing timelike geodesic $\sigma:[0,1] \to \mathcal M$ from $p_2$ to $p_3$, let $\Delta(p_1^*,p_2^*,p_3^*)$ be the (up to isometries unique) comparison triangle in $\mathbb L^2(-\delta)$, i.e. $p_1^* \ll p_2^* \ll p_3^*$ and $\ell(p_1,p_2) = \bar{\ell}_{-\delta}(p_1^*,p_2^*)$, $\ell(p_1,p_3) = \bar{\ell}_{-\delta}(p_1^*,p_3^*)$ and $L_\mathsf g(\sigma) = \bar{\ell}_{-\delta}(p_2^*,p_3^*)$. Given any point $q$ on the side $p_2p_3$ (i.e., on $\sigma$) and the corresponding point $q^*$ on the side of $p_2^{\ast}p_3^{\ast}$ (i.e., if $q = \sigma_t$, the unique $t$-midpoint on the side $p_2^*p_3^*$), we have
\begin{equation} \label{eq: triangle comparison}
    \ell(p_1,q) \leq \bar{\ell}_{-\delta}(p_1^*,q^*).
\end{equation}

\label{Theorem: Toponogov convexity version}
Let $(\mathcal M,\mathsf g)$ be a globally hyperbolic spacetime with timelike sectional curvature bounded below by $-\delta \leq 0$. Then for any $p \in M$ and any (not necessarily maximizing) timelike geodesic $\gamma:[0,1] \to \mathcal M$ contained in $I^+(p)$, the function $f_\delta:[0,1] \to \mathbb R$ defined by
\begin{equation}
    f_\delta(t):=\begin{cases}
        \frac{\ell(p,\gamma_t)^2}{2}, \quad \delta = 0,\\
        \frac{\cosh(\sqrt{\delta} \, \ell(p,\gamma_t)) - 1}{\delta}, \quad {\delta > 0},
    \end{cases}
\end{equation}
satisfies the following differential inequality in the distributional sense:
\begin{equation}
    f_\delta''(t) \geq L_\mathsf g(\gamma)^2 (1 {+} \delta f_\delta(t)). 
\end{equation}

\label{Thm : Law of cosines} \emph{(Hyperbolic law
of cosines \cite[Lem.\ 2.8]{Beran_2023})} 
\begin{enumerate}[label = (\Alph*)]
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} Let $\delta \geq 0$ and $\mathbb L^2(-\delta)$ be the simply connected $2$-dimensional spacetime with timelike sectional curvature equal to $-\delta$ and time separation function given by $\ell = \overline{\ell}_{-\delta}$. Consider a timelike triangle $\Delta (p_1,p_2,p_3)$ in $\mathbb L^2(-\delta)$ with sidelengths
    \[
    \ell (p_1,p_2) =a, \qquad \ell(p_2, p_3) = b, \qquad \ell(p_1,p_3)=c+d,
    \]
    and suppose that $p_1p_3$ is the longest side, namely $a+b \leq c+d$. Choose now a point $q$ on the maximizing timelike geodesic $\sigma$ connecting $p_1$ to $p_3$ such that
    \[
    \ell (p_1, q)= c, \qquad \ell (q, p_3) = d. 
    \]
    We suppose $q \leq p_2$ or $p_2 \leq q$ and define $x:= \max \{ \ell (q, p_2), \ell(p_2,q) \}$. Then the following formulas hold:
    \begin{itemize}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[i)] If $\delta =0$, then 
        \begin{equation*}
        x^2 = \frac{c b^2+a^2 d}{c+d} - cd.
        \end{equation*}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[ii)] If $\delta >0$, then 
        \begin{equation*}
        \begin{split}
    \cosh( \sqrt{\delta}x ) =&\, \left ( \cosh( \sqrt{\delta}b ) - \cosh( \sqrt{\delta}a) \cosh( \sqrt{\delta}(c+d))  \right ) \cdot  
    \dfrac{\sinh (\sqrt{\delta}c )}{\sinh (\sqrt{\delta}(c+d)) }\\
    &\, + \cosh ( \sqrt{\delta} a) \cosh ( \sqrt{\delta} c).
    \end{split}
    \end{equation*}
    In particular, the following asymptotic formula holds:
    \begin{equation*}
    x^2 = \dfrac{cb^2+a^2d}{c+d} - cd + O(\delta (c+d)^4) \text{ for } \delta \downarrow 0 \text{ or } (c+d) \downarrow 0.
    \end{equation*}
    \end{itemize}

    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} Similarly to $(A)$, consider a timelike triangle $\Delta(p_1,p_2,p_3)$ in $\mathbb L^2(-\delta)$ with sidelengths $a = \ell(p_1,p_2)$, $b+c = \ell(p_2,p_3)$ and $d=\ell(p_1,p_3)$, such that $a+b+c \leq d$. Let $q$ be a point on the side from $p_2$ to $p_3$ such that $\ell(p_2,q) = b$ and $\ell(q,p_3) = c$. Then for $x:=\ell(p_1,q)$ the following formulas hold:
    \begin{itemize}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[i)] If $\delta = 0$, then
        \begin{equation*}
            x^2 = \frac{bd^2 + a^2 c}{b+c}-bc.
        \end{equation*}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[ii)] If $\delta > 0$, then
        \begin{align*}
            \cosh(\sqrt{\delta} x) = &(\cosh(\sqrt{\delta d}) - \cosh(\sqrt{\delta}a)\cosh(\sqrt{\delta}(b+c))) \cdot \frac{\sinh(\sqrt{\delta} b)}{\sinh(\sqrt{\delta}(b+c))}\\ 
            &+ \cosh(\sqrt{\delta}a) \cosh(\sqrt{\delta}b).
        \end{align*}
        In particular, the following asymptotic formula holds:
        \begin{equation*}
            x^2 = \frac{bd^2 + a^2 c}{b+c}-bc + O(\delta d^4) \text{ for } \delta \downarrow 0 \text{ or } d \downarrow 0.
        \end{equation*}
    \end{itemize}
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} In analogy with the previous cases, consider a timelike triangle $\Delta(p_1,p_2,p_3)$ in $\mathbb L^2(-\delta)$ with sidelengths $\ell(p_1,p_2) = a+b$, $\ell(p_2,p_3) = c$, $\ell(p_1,p_3) = d$. Let $q$ be the point on the side from $p_1$ to $p_2$ such that $\ell(p_1,q) = a$, $\ell(q,p_2) = b$. Denote by $x:=\ell(q,p_3)$. Then
    \begin{itemize}
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[i)] If $\delta = 0$, then
        \begin{equation*}
            x^2 = \frac{bd^2 + c^2 a}{b+a}-ba.
        \end{equation*}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[ii)] If $\delta > 0$, then
        \begin{align*}
            \cosh(\sqrt{\delta} x) = &(\cosh(\sqrt{\delta d}) - \cosh(\sqrt{\delta}c)\cosh(\sqrt{\delta}(b+a))) \cdot \frac{\sinh(\sqrt{\delta} b)}{\sinh(\sqrt{\delta}(b+a))}\\ 
            &+ \cosh(\sqrt{\delta}c) \cosh(\sqrt{\delta}b).
        \end{align*}
        In particular, the following asymptotic formula holds:
        \begin{equation*}
            x^2 = \frac{bd^2 + c^2 a}{b+a}-ba + O(\delta d^4) \text{ for } \delta \downarrow 0 \text{ or } d \downarrow 0.
        \end{equation*}
    \end{itemize}
    \end{enumerate}

A \emph{metric spacetime} is a pair $(X,\ell)$, where $X$ is a set and $\ell:X^2 \to \{-\infty\} \cup [0,\infty]$ is a function (called \emph{time separation}) satisfying
\begin{equation}
    \ell(x,z) \geq \ell(x,y) + \ell(y,z)
\end{equation}
for all $x,y,z \in X$. Here, the right-hand side is understood to be $-\infty$ if one of the summands is $-\infty$. We say $(X,\ell)$ is \emph{bounded} if $\ell$ is bounded above.

\label{D:d_LGH}
Let $(X,\ell^X)$ and $(Y,\ell^Y)$ be bounded metric spacetimes.
\begin{enumerate}
\refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} Given a correspondence $\mathcal R \subseteq X \times Y$, its \emph{distortion} is
\begin{equation}
    \mathrm{dis}(\mathcal R):= \sup \{ |\ell^X_+(x,x') - \ell^Y_+(y,y')| : (x,y),(x',y') \in \mathcal R\}.
\end{equation}
\refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} The \emph{Lorentzian Gromov--Hausdorff distance} $\mathsf d_{LGH}(X,Y)$ is defined as
\begin{equation}
\label{d_{LGH}}
    \mathsf d_{LGH}(X,Y) := \inf_{\mathcal R} \mathrm{dis}(\mathcal R), 
\end{equation}
where the infimum runs over all correspondences $\mathcal R \subseteq X \times Y$.
\end{enumerate}

\label{Definition: Lorentzian products}
Given a metric space $(Z, \mathsf d)$, consider the product $\mathbb R \times Z$. Define the time separation function $\ell_{\mathbb R \times Z}:(\mathbb R \times Z)^2 \to \{-\infty\} \cup [0,\infty)$ on $\mathbb R \times Z$ via the formula
\begin{equation}\label{Lorentzian products}
    \ell_{\mathbb R \times Z}((s,x),(t,y)):=\begin{cases}
        \sqrt{(t-s)^2 - \mathsf d(x,y)^2}, & t-s \geq \mathsf d(x,y),\\ -\infty & \text{otherwise}.
    \end{cases}
\end{equation}
We call $(\mathbb R \times Z, \ell_{\mathbb R \times Z})$ the Lorentzian product over $(Z,\mathsf d)$.

\label{Lemma: On Lorentzian products}
Given any metric space $(Z,\mathsf d)$, the Lorentzian product $(\mathbb R \times Z, \ell_{\mathbb R \times Z})$ is a metric spacetime. Moreover, on any causal diamond of the form $J((-R,x_0),(R,x_0)) \subseteq \mathbb R \times Z$ for any $x_0 \in Z$ and $R \geq 0$, the time separation is bounded above by $2R$. In particular, any such causal diamond is a bounded metric spacetime when endowed with the restriction of the 
time separation.

\label{Remark: i^0}
If $J(x,y)$ is a causal diamond in a globally hyperbolic spacetime $(\mathcal M,\mathsf g)$ (or in a product metric spacetime $(\mathbb R \times Z, \ell_{\mathbb R \times Z})$), we denote by $i^0$ (or $\bar i^0$) the set of points $w \in J(x,y)$ such that $\ell(p,w)  \leq 0$ and $\ell(w,p) \leq 0$ for all $p \in J(x,y)$. 
When we want to compute the Lorentzian Gromov--Hausdorff distance, we will first collapse the set $i^0$ and $\bar i^0$ (if non-empty) to a point, which is exactly the setting considered by Minguzzi--Suhr \cite{MinguzziSuhr22}. Since these quotients are bounded metric spacetimes with respect to the restriction of $\ell$, and the positive part of this restriction agrees with the positive part of $\ell$ on $J(x,y)$, for the purposes of computing the Lorentzian Gromov--Hausdorff distances between two such causal diamonds, one may choose to collapse $i^0$ and $\bar i^0$ separately without changing the result.

Let $(\mathcal M,\mathsf g)$ be a globally hyperbolic spacetime and $C \subseteq \mathcal M$.
\begin{enumerate}
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[(i)] A function $f:C \subseteq \mathcal M \to \mathbb R$ is called \textit{causal} if $f(x) \leq f(y)$ whenever $x,y \in C$ with $x\leq y$. It is called \textit{anti-causal} if instead $f(y) \leq f(x)$ whenever $x,y \in C$ with $x \leq y$. 
    \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[(ii)] A function $f:C \subseteq \mathcal M \to \mathbb R$ is called $c$-steep (for some number $c \geq 0$) if for every $x,y \in C$ we have that
    \begin{equation}
        f(y) - f(x) \geq c\ell(x,y).
    \end{equation}
    The function $f$ is called $c$-\textit{antisteep} if instead for all $x,y \in C$ we have that
    \begin{equation}
        f(x) - f(y) \geq c \ell(x,y).
    \end{equation}
\end{enumerate}

A subset $C \subseteq \mathcal M$ of a globally hyperbolic spacetime $(\mathcal M,\mathsf g)$ is called \emph{causally convex} 
    if $J(x,y) \subseteq C$ whenever $x$ and $y$ are in $C$. 
    Equivalently, for all $x,y \in C$, any causal curve segment from $x$ to $y$ is entirely contained in $C$.

\label{Theorem: convexityoftimeseparation}
Let $(\mathcal M,\mathsf g)$ be a globally hyperbolic spacetime with timelike sectional curvature bounded below by $-\delta \leq 0$ and let $\Upsilon:[-L,L] \to \mathcal M$ be a timelike maximizing geodesic of length $2L$. Then, for a fixed constant $0 < R < \frac{L}{2}$, the Lipschitz continuous causal function $\mathrm{md}^{-\delta}(\ell(\Upsilon_{-L}, \cdot))$ and the Lipschitz continuous anti-causal function $\mathrm{md}^{-\delta}(\ell(\cdot,\Upsilon_L))$ are causally $\lambda$-convex on the open connected causally convex set $I(\Upsilon_{-R},\Upsilon_R)$, where 
\begin{equation}\label{md}
    \mathrm{md}^{-\delta}(t):=\begin{cases}
        \frac{\cosh(\sqrt{\delta} t) - 1}{\delta}, & {\delta > 0},\\
        \frac{t^2}{2}, & \delta = 0,
    \end{cases}
\end{equation}
and
\begin{equation}
    \lambda = \lambda(\delta, L \, | \, R) = \cosh(\sqrt{\delta} (L-R)).
\end{equation}
In fact, the two functions are even causally $\lambda$-convex (with the same $\lambda$ as above) on the larger open causally convex set $\{\ell(\Upsilon_{-L}, \cdot) > L - R\} \cap \{\ell(\cdot,\Upsilon_L) > L - R\} \subseteq I(\Upsilon_{-L},\Upsilon_L)$. Moreover, $\lambda(\delta,L \, |R) \downarrow 1$ as $(\delta, L^{-1}) \to 0$ if $\sqrt{\delta} L \to 0$.

\label{Lemma: Monotonicitysupergradient}
Let $(\mathcal M,\mathsf g)$ be globally hyperbolic, $C \subseteq \mathcal M$ be open and causally convex, $f:C \to \mathbb R$ be $\lambda$-convex causal (or anti-causal), and $\sigma:[0,1] \to C$ be a maximizing timelike geodesic connecting $x:=\sigma_0$ to $y:= \sigma_1$. Then any $v \in \partial_\leq f(x)$ and $w \in \partial_\leq f(y)$ satisfy
\begin{equation}
    w[\sigma'_1] - v[\sigma'_0] \geq \lambda \ell(x,y)^2.
\end{equation}

Let us write $\sigma_t = \exp_x(t\sigma'(0))$ for $t \in [0,1]$. Using the definition of causal subdifferential as well as causal $\lambda$-convexity, we get
    \begin{align*}
        v[\sigma'_0] \leq \limsup_{t \downarrow 0} \frac{f(\sigma_t) - f(\sigma_0)}{t} \leq f(y) - f(x) - \frac{\lambda}{2} \ell(x,y)^2.
    \end{align*}
    Similarly, considering the past reparametrization of $\sigma$, we obtain
    \begin{align*}
        w[\sigma'_1] \geq f(y) - f(x) + \frac{\lambda}{2}\ell(x,y)^2.
    \end{align*}
    Adding these two estimates yields the claim.

\label{Theorem: local existence}
    Let $(\mathcal M,\mathsf g)$ be a globally hyperbolic spacetime. Let $C \subseteq \mathcal M$ be a connected causally convex open subset and $f: C \rightarrow \mathbb R$ a $c$-steep causally convex function for some $c > 0$. Then $f$ is locally Lipschitz on $C$ and for every $x \in C$, there exists a unique locally Lipschitz causal curve $\gamma:[0,T) \to C$ for some maximal $T>0$ such that
    \begin{itemize}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[i)] $\dot \gamma_t ^{\flat} \in \partial_{\leq} f(\gamma_t)$ for a.e. $t \in [0,T)$ and $\gamma_0=x$, and
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}}[ii)] $ \frac{d}{ds} \big |_{s=t} \, f(\gamma_s) = \| \dot \gamma_t \|_\mathsf g^2 = \left ( \inf_{y \gg \gamma_t} \frac{f(y) - f(\gamma_t)}{\ell(\gamma_t,y)} \right )^2$ for a.e. $t \in [0,T)$.
    \end{itemize}
    Moreover, if $C$ has compact closure in $M$ we have that $\gamma_T:=\lim_{t \uparrow T} \gamma_t \in \partial C$. Such a curve $\gamma$ is called the \emph{gradient flow of $f$ starting at $x$}.

    In addition, the gradient flow is stable in the following sense: If $(x_n) \downarrow x$ in $C$, i.e., $x_{n+1} \leq x_n$ for all $n$ and $x_n \to x$, then the (unique) gradient flows of $f$ starting at $x_n$ converge locally uniformly to the (unique) gradient flow of $f$ starting at $x$.

\label{Theorem: main theorem}
Fix $R > 0$. Then for every $\delta \geq 0$ and $L \gg R$ there exists a quantity $\Psi = \Psi(\delta,L \, | R)$ with $\Psi(\delta,L \, | R) \to 0$ as $(\delta, L^{-1}) \to 0$, such that the following holds: If $(\mathcal M,\mathsf g)$ is a globally hyperbolic spacetime with timelike sectional curvature bounded below by $-\delta \leq 0$ and there exists a maximizing timelike geodesic $\Upsilon:[-L,L] \to \mathcal M$ parametrized by Lorentzian arclength, then there exists a pointed metric space $(X,\mathsf d, x_0)$ such that
\begin{equation}
    {\mathsf d}_{LGH}(J^\mathcal M(\Upsilon_{-R},\Upsilon_R), J^{\mathbb R \times X}((-R,x_0),(R,x_0))) \leq \Psi(\delta,L\,|\,R).
\end{equation}

\label{Prop: first expansion rate estimate}
Let $C$ be open, connected and causally convex, $f:C \to \mathbb R$ a causally $\lambda$-convex $c$-steep function for some $c > 0$ and $\lambda \in \mathbb R$. Consider two gradient flow curves $\alpha,\beta:[0,T] \to C$ {of $f$} with $\alpha_0 \leq \beta_0$, and $[0,T]$ a subset of the intersection of their maximal domains. Then for all $t \in [0,T]$,
\begin{equation}\label{first}
    \ell(\alpha_t,\beta_t)^2 \geq e^{2\lambda t} \ell(\alpha_0,\beta_0)^2 \geq (1+ 2\lambda t) \, \ell(\alpha_0,\beta_0)^2.
\end{equation}
Moreover, if $\lambda \geq 0$, then
\begin{equation*}
    \ell(\alpha_t,\beta_t)^2 \geq (1+ 2\lambda t)\ell(\alpha_0,\beta_0)^2 \geq 0
\end{equation*}
for all $t \in [0,T]$. Thus, if $\lambda \geq 0$, then $\alpha_t \leq \beta_t$ for every $t \in [0,T]$.

We will show the claim assuming that $\alpha_0 \ll \beta_0$, the case $\alpha_0 \leq \beta_0$ then follows from the stability of the gradient flow. Since $\alpha,\beta$ are (locally Lipschitz) continuous and $\alpha_0 \ll \beta_0$, there exists $t^* > 0$ such that $\alpha_t \ll \beta_t$ for all $t \in [0,t^*)$. For each $t \in [0,t^*)$, let $\sigma^{(t)}:[0,1] \to C$ be a timelike maximizing geodesic connecting $\alpha_t = \sigma^{(t)}_0$ to $\beta_t:=\sigma^{(t)}_1$. Denote by $m^{(t)}:=\sigma^{(t)}_{1/2}$ the midpoint of $\sigma^{(t)}$ and note that $m^{(t)}$ is neither in the future causal cut locus of $\alpha_t$ nor in the past causal cut locus of $\beta_t$. By construction, $\alpha_t \ll m^{(t)} \ll \beta_t$ and
    \begin{align}\label{eq: equalitymidpoint}
        \ell(\alpha_t,\beta_t) = \ell(\alpha_t,m^{(t)}) + \ell(m^{(t)},\beta_t).
    \end{align}
    For each $t \in [0,t^*)$, by openness of $\ll$, we may find $\eta' > 0$ such that $t + \eta' < t^*$ and $\alpha_{t+\eta} \ll m^{(t)} \ll \beta_{t+\eta}$ for all $0 < \eta \leq \eta'$, and the reverse triangle inequality yields
    \begin{align}\label{eq: inequalitymidpoint}
    \ell(\alpha_{t+\eta},\beta_{t+\eta}) \geq \ell(\alpha_{t+\eta},m^{(t)}) + \ell(m^{(t)}, \beta_{t+\eta}).
    \end{align}
    Subtracting \eqref{eq: equalitymidpoint} from \eqref{eq: inequalitymidpoint} and dividing by $\eta$ yields
    \begin{align}\label{eq: midpointdifferencequotient}
        \frac{\ell(\alpha_{t+\eta},\beta_{t+\eta}) - \ell(\alpha_t,\beta_t)}{\eta} \geq \frac{\ell(\alpha_{t+\eta},m^{(t)}) - \ell(\alpha_t,m^{(t)})}{\eta} + \frac{\ell(m^{(t)},\beta_{t+\eta}) - \ell(m^{(t)},\beta_t)}{\eta}.
    \end{align}
    Since $m^{(t)}$ is neither a future cut point of $\alpha_t$ nor a past cut point of $\beta_t$, the functions $s \mapsto \ell(\alpha_s,m^{(t)})$ and $s \mapsto \ell(m^{(t)},\beta_s)$ (defined for $s$ close to $t$) are differentiable at $s=t$. Thus, by taking the $\liminf$ as $\eta \downarrow 0$, the terms on the right-hand side of \eqref{eq: midpointdifferencequotient} become actual limits. In particular, for all $t$ at which $\alpha$, $\beta$, and $t \mapsto \ell(\alpha_t,\beta_t)$ are differentiable (by Lipschitz continuity, these are almost all $t$), {
 the first variation formula (cf. \cite[p.\ 264]{bookONeill}) yields}
    \begin{align}
        &\lim_{\eta \downarrow 0} \frac{\ell(\alpha_{t+\eta},m^{(t)}) - \ell(\alpha_t,m^{(t)})}{\eta} = -\frac{1}{\ell(\alpha_t,\beta_t)} \mathsf g((\sigma^{(t)})'(0),\alpha'_t),\\
        &\lim_{\eta \downarrow 0} \frac{\ell(m^{(t)},\beta_{t+\eta}) - \ell(m^{(t)},\beta_t)}{\eta} = \frac{1}{\ell(\alpha_t,\beta_t)} \mathsf g((\sigma^{(t)})'(1),\beta'_t).
    \end{align}
    Using this, together with the monotonicity property from Lemma \ref{Lemma: Monotonicitysupergradient}, noting that $(\alpha'_t)^{\flat} \in \partial_\leq f(\alpha_t)$ and $(\beta'_t)^{\flat} \in \partial_\leq f(\beta_t)$, we obtain for almost every
    $t \in [0,t^*)$ that
    \begin{align}
        \lim_{\eta \downarrow 0} \frac{\ell(\alpha_{t+\eta},\beta_{t+\eta})- \ell(\alpha_t,\beta_t)}{\eta} &\geq \frac{\mathsf g((\sigma^{(t)})'_1,\beta'_t)-\mathsf g((\sigma^{(t)})'_0,\alpha'_t)}
        {\ell(\alpha_t,\beta_t)} \\
        &= \frac{(\beta'_t)^{\flat}[(\sigma^{(t)})'_1] - (\alpha'_t)^{\flat}[(\sigma^{(t)})'_0]}{\ell(\alpha_t,\beta_t)}\\
        &\geq \lambda \ell(\alpha_t,\beta_t).
    \end{align}
    Integrating this inequality yields the claim for $t \in [0,t^*)$. Continuity yields the claim for $t = t^*$, then a connectedness argument yields it for all $t \in [0,T]$.

\label{L:gradient estimate}
    \label{variation inequality} Let $(\mathcal M,\mathsf g)$ be a globally hyperbolic spacetime, let $x \ll y$ be any two points, and let $\sigma:[0,1] \to \mathcal M$ be a maximizing timelike geodesic from $x$ to $y$. 
    Let $\gamma:[0,T] \to \mathcal M$ be any future causal curve starting at $y$ which is right-differentiable at $t= 0$, then 
    \begin{equation}\label{gradient estimate}
    \liminf_{t \rightarrow 0^{+}} \frac{\ell(x, \gamma_t)- \ell(x,y)}{t} \geq \frac{ \mathsf g(\sigma'_1, \gamma_0')}{ \ell(x,y)}.
    \end{equation}
    In particular,   
    \begin{equation}
        \frac{d}{dt}\bigg|^+_{t = 0} \frac{1}{2}\ell(x,\gamma_t)^2 \geq \mathsf g(\gamma_0', \sigma'_1).
    \end{equation}

\label{Prop: Second mainstream expansion}
Let $(\mathcal M,\mathsf g)$ be globally hyperbolic with timelike sectional curvature bounded below by $-\delta \leq 0$, and let $\Upsilon:[-L,L] \to \mathcal M$ be a maximizing timelike geodesic parametrized by proper time. Let $F(x):=\ell(\Upsilon_{-L},x)$ and let $\gamma^1,\gamma^2:[0,T] \to H$ be two gradient flow curves of $\mathrm{md}^{-\delta} \circ F$. Suppose that $\gamma^1_0 \leq \gamma^2_0$. Then for every $t \in [0,T]$,
\begin{equation}
\begin{split}
    \ell(\gamma_0^1,\gamma_t^2)^2 & \geq  \ell(\gamma_0^1,\gamma^2_0)^{2} + 2\int_0^t \int_0^s (\mathrm{md}^{-\delta})'(F(\gamma^2_r))^2 \, dr \, ds \\ & \qquad \qquad +2t(\mathrm{md}^{-\delta}(F(\gamma^2_0)) - \mathrm{md}^{-\delta}(F(\gamma^1_0))) + \lambda \int_0^t \ell(\gamma^1_0,\gamma^2_s)^{2} \, ds.
    \end{split}
\end{equation}

Again we may suppose that $\gamma_0^1 \ll \gamma_0^2$. The case $\gamma_0^1 \leq \gamma_0^2$ follows from gradient flow stability. 
    Fix $f(x):=\mathrm{md}^{-\delta}(F(x))$. Since $r \mapsto f(\gamma^2_r)$ is increasing, then
    \begin{equation*}
        f(\gamma_s^2) - f(\gamma^2_0) \geq \int_0^s \frac{d}{dr}  f(\gamma^2_r) \, dr.
    \end{equation*}
    By properties of the gradient flow, the fact that $F$ is $1$-steep, and since $f(\gamma^2_r)$ is differentiable a.e., it follows for a.e. $r$ that
    \begin{equation*}
        \frac{d}{dr} f(\gamma_r^2) = (\mathrm{md}^{-\delta})'(F(\gamma^2_r)) \frac{d}{dr} \, F(\gamma^2_r) \geq (\mathrm{md}^{-\delta})'(F(\gamma^2_r)) \|\dot \gamma^2_r\| \geq ((\mathrm{md}^{-\delta})'(F(\gamma^2_r))^2.
    \end{equation*}
    This gives the estimate
    \begin{equation}
    \label{eq: fgamma^2_1 - fgamma^2_0 estimate}
        f(\gamma_s^2) - f(\gamma^2_0) \geq \int_0^s ((\mathrm{md}^{-\delta})'(F(\gamma^2_r))^2 \, dr. 
    \end{equation}
    {Now} connect $\gamma_0^1$ to $\gamma^2_s$ by a maximizing timelike geodesic $\sigma^{(s)}:[0,1] \to H$. Using the $\lambda$-convexity of $f$ along $\sigma^{(s)}$ and the fact that $(\dot \gamma_s^2)^{\flat} \in \partial_\leq f ( \gamma^2_s)$, we have that
    \begin{equation}
        (\dot \gamma_s^2)^{\flat} [\dot \sigma^{(s)}_1] \geq \lim_{\varepsilon \rightarrow 0} \frac{f( \sigma^{(s)}_{1})- f(\sigma^{(s)}_{1- \varepsilon} )}{\varepsilon} \geq f(\sigma_1^{(s)}) - f(\sigma_0^{(s)} ) + \frac{\lambda}{2} \ell(\gamma_0^1, \gamma_s^2)^2 ,
    \end{equation}
    and so
    \begin{equation}\label{EVI 2a}
        g( \dot \gamma_s^2 , \dot \sigma^{(s)}_1 ) \geq f(\gamma_s^{2} ) - f(\gamma_0^1) + \frac{\lambda}{2} \ell(\gamma_0^1, \gamma_s^2)^2
    \end{equation}
    Now, using Lemma \ref{variation inequality}, we obtain for a.e. $s \in [0,T]$ that
    \begin{equation} \label{eq: EVI 2}
        \dfrac{d}{dt}\bigg{|}^+_{t=s} \frac{1}{2} \ell(\gamma^1_0, \gamma_t^2)^2 \geq \mathsf g( \dot \gamma_s^2 , \dot \sigma^{(s)}_1 )  .
    \end{equation}
    Next we can {combine \eqref{EVI 2a}}, \eqref{eq: EVI 2}, and \eqref{eq: fgamma^2_1 - fgamma^2_0 estimate} to get
    \begin{equation}
        \dfrac{d}{dt}\bigg{|}^+_{t=s} \frac{1}{2} \ell(\gamma^1_0, \gamma_t^2)^2 \geq f(\gamma_0^2) - f(\gamma_0^1) +\int_0^s ((\mathrm{md}^{-\delta})'(F(\gamma^2_r))^2 \, dr + \frac{\lambda}{2} \ell(\gamma_0^1, \gamma_s^2)^2 .\label{eq3.20}
    \end{equation}
    The conclusion follows by integrating \eqref{eq3.20} on $s \in [0,t]$ and noticing that 
    \[
    \frac{1}{2} \ell(\gamma_0^1, \gamma_t^2)^2 - \frac{1}{2} \ell(\gamma_0^1, \gamma_0^2)^2 \geq \int_0^t \dfrac{d}{d\tau}\bigg{|}^+_{\tau=s} \frac{1}{2} \ell(\gamma^1_0, \gamma_{\tau}^2)^2 ds
    \]
    holds by monotonicity of $s \mapsto \frac{1}{2} \ell(\gamma_0^1, \gamma_s^2)^2$.

\label{Prop: Second upstream expansion}
In the setting of Proposition \ref{Prop: Second mainstream expansion}, let $\gamma^1,\gamma^2:[0,T] \to H$ be two gradient flow curves of $\mathrm{md}^{-\delta} \circ F$,
and suppose for some $t \in [0,T]$ we have that $\gamma^1_t \leq \gamma^2_0$. Then
\begin{equation}
\begin{split}
    \ell(\gamma_t^1,\gamma_0^2)^2 & \geq \ell(\gamma_0^1,\gamma_0^2)^2 + 2 \int_0^t \int_0^s (\mathrm{md}^{-\delta})'(F(\gamma^1_r))^2 \, dr ds \\
    & \qquad \qquad {-} 2t(\mathrm{md}^{-\delta}(F(\gamma_0^2)) - \mathrm{md}^{-\delta}(F(\gamma_0^1)))
    + \lambda \int_0^t \ell(\gamma^1_s,\gamma_0^2)^2 \, ds.
\end{split}
\end{equation}

\label{Prop: Final second expansion}
In the setting of Proposition \ref{Prop: Second mainstream expansion}, suppose $\gamma^1,\gamma^2:[0,T] \to H$ are two gradient flows with $\gamma_0^1 \leq \gamma_0^2$. 
For all $s,t \in [0,T]$. If $s\le t$ then
\begin{equation}\label{final 2a}
    \begin{split}\ell(\gamma^1_s,\gamma^2_t)^2 &\geq e^{2\lambda s} \bigg(\ell(\gamma_0^1,\gamma_0^2)^2 + 2 \int_0^{t-s} \int_0^r (\mathrm{md}^{-\delta})'(F(\gamma^2_\xi))^2 \, d\xi \, dr  \\
        &\qquad   +2(t-s) (\mathrm{md}^{-\delta}(F(\gamma_0^2)) - \mathrm{md}^{-\delta}(F(\gamma_0^1))) + \lambda \int_0^{t-s} \ell(\gamma_0^1,\gamma_\xi^2)^2 \, d\xi\bigg) .
    \end{split}
\end{equation}
If instead $s\geq t$ but $\gamma_{s-t}^1 \leq \gamma_0^2$ then
\begin{equation}\label{final 2b}
    \begin{split}
        \ell(\gamma^1_s,\gamma^2_t)^2 &\geq e^{2\lambda t} \bigg(\ell(\gamma_0^1,\gamma_0^2)^2 + 2 \int_0^{s-t} \int_0^r (\mathrm{md}^{-\delta})'(F(\gamma^1_\xi))^2 \, d\xi \, dr  \\
        &\qquad   +2(s-t) (\mathrm{md}^{-\delta}(F(\gamma_0^1)) - \mathrm{md}^{-\delta}(F(\gamma_0^2))) + \lambda \int_0^{s-t} \ell(\gamma_\xi^1,\gamma_0^2)^2 \, d\xi\bigg) .
    \end{split}
\end{equation}

\label{Cor: Compact rewriting of second expansion estimates}
Let $(\mathcal M,\mathsf g)$ globally hyperbolic with timelike sectional curvature bounded below by $-\delta < 0$, $\Upsilon:[-L,L] \to \mathcal M$ a timelike maximizing geodesic parametrized by proper time. Let $F(x):=\ell(\Upsilon_{-L},x)$, and $\gamma^1,\gamma^2:[0,T] \to H $ be two gradient flow curves of $\mathrm{md}^{-\delta} \circ F$ satisfying $\gamma^1_0 \leq \gamma^2_0$. Let $s,t \in [0,T]$. Assume either $s \leq t$ or $s > t$ and $\gamma^1_{s - t} \leq \gamma^2_0$. Then
\begin{equation}\label{eq3.24}
    \begin{split}
        \ell(\gamma^1_s,\gamma^2_t)^2 &\geq e^{2 \lambda \min \{ s,t \} } \bigg( \ell(\gamma_0^1,\gamma_0^2)^2 + (t-s)^2(\mathrm{md}^{-\delta})'(F(\gamma_0^1))^2 \\
        &\qquad \qquad  + 2(t-s) (\mathrm{md}^{-\delta}(F(\gamma_0^2)) - \mathrm{md}^{-\delta}(F(\gamma_0^1)))\bigg).
    \end{split}
\end{equation}

The reparametrization $g=g(t)$ satisfies 
    {\eqref{eq: reparametrization}.}
    {Since $(\mathrm{md}^{-\delta})' (\cdot)$ 
    is nondecreasing}
    and Lemma \ref{lem: monotonicity 1} 
    {yields $\gamma_{g(t)} \in J(\Upsilon_{h_{\tilde R}(g(t))},\Upsilon_{h_R(g(t))})$, we find}
    \begin{align*}
    \frac{1}{(\mathrm{md}^{-\delta})' (F(\Upsilon_{h_R\circ g(t)}))} \leq g'(t) 
    &\leq \frac{1}{(\mathrm{md}^{-\delta})' (F(\Upsilon_{h_{\tilde R}\circ g(t)}))}.
    \end{align*}
    The 
    {lower bound} can be computed explicitly:
    \begin{align*}
    \frac{1}{(\mathrm{md}^{-\delta})' (F(\Upsilon_{h_R\circ g(t)}))}&=
        \frac{1}{(\mathrm{md}^{-\delta})'(h_{R}(g(t)) + L)} 
        \\& = \sqrt{\delta} \, \frac{1-e^{2g(t) \tanh^2(\sqrt{\delta}(L+{R})/2)}}{ 2e^{g(t)} \tanh(\sqrt{\delta}(L+{R})/2)}
    \end{align*}
    {where the formula ${\rm arctanh} s = \log \sqrt{\frac{1+s}{1-s}}$ and Equation \eqref{hed} have been used.}
    Given that $\sqrt{\delta} L \to 0$, an explicit computation shows that the right hand side is of the form $\frac{1 + \Psi(\delta,L)}{L+R}e^{-g(t)}$. Multiplying by $e^{g(t)}$ and integrating  gives us that
    \begin{equation}
    \label{eq: bounds on g}
        \log \left( 1 + \frac{t + \Psi(\delta,L)}{L + R} \right) \leq g(t) \leq \log \left( 1 + \frac{t + \Psi(\delta,L)}{L + \tilde{R}}  \right).
    \end{equation}
    Using now the monotonicity established in Lemma \ref{lem: monotonicity 1}, we get that $\bar \gamma_t \in J(\Upsilon_{s_-(t)},\Upsilon_{s_+(t)})$, where $s_\pm(t)$ have the claimed form. Let us demonstrate this for $s_-(t)$:
    \begin{align*}
        s_-(t) &= h_{\tilde R}(\log(1 + (t + \Psi(\delta,L))/(L+{R}))) 
        \\&= (L + \tilde R) (1 + (t+ \Psi)/(L+R)) - L + \Psi\\
        &= \tilde R + \frac{L + \tilde R}{L + R}(t + \Psi) + \Psi \\
        &= \tilde R + t + \Psi,
    \end{align*}
    where in the last equality we use $t \in [0,4]$ to collect the term $t(\tilde R - R)/(L + R)$ into the term $\Psi$.

If $\delta=0$ the previous lemma gets much simpler and more explicit. Let $\Upsilon_{\tilde{R}} \leq x \leq \Upsilon_{R}$ and $g$ be the reparametrization of the modified flow starting at $x$. Then, following the proof of the lemma
    we get that
    \begin{equation*}
    \frac{1}{(L+R) e^{g(t)}} \leq g'(t) \leq  \frac{1}{(L+ \tilde R) e^{g(t)}}
    \end{equation*}
    and the ODE comparison produces 
    \begin{equation*}
    \log \left ( 1+ \frac{t}{L+R} \right ) \leq g(t) \leq \log \left ( 1+ \frac{t}{L+ \tilde{R}} \right ).
    \end{equation*}
    We remark that the last inequality holds for all $t \leq  4$
    and there is no blow up for the reparametrization. Moreover we get that
    \[
    \overline{\gamma}_t \in J( \Upsilon_{\tilde R + \frac{L+ \tilde R}{L+R} t} , \Upsilon_{R + \frac{L+R}{L+ \tilde R} t})
    \]
    for every $t \leq 4$ and every $x \in J( \Upsilon_{\tilde R}, \Upsilon_{R})$. Notice that this is compatible with the previous lemma since $\frac{L+ \tilde{R}}{L+R}t = t - \frac{R -\tilde R}{L+R}t = t + \Psi(\delta, L)$.

\label{Prop: second estimate for reparametrized flow}
Let $(\mathcal M,\mathsf g)$ be globally hyperbolic with timelike sectional curvature bounded below by $-\delta \leq 0$ and let $\Upsilon:[-L,L] \to \mathcal M$ be a timelike maximizing geodesic parametrized by Lorentzian arclength. 
Let $F(x):=\ell(\Upsilon_{-L},x)$, and $\gamma^1,\gamma^2:[0,T] \to \mathcal M$ be two gradient flow curves of $\mathrm{md}^{-\delta} \circ F$ starting in $ I(\Upsilon_{\tilde R},\Upsilon_{R})$, where $-10 < \tilde R \leq R < 10 \le L/2$, and satisfying $\gamma^1_0 \leq \gamma^2_0$. Let $g_1,g_2$ be the reparametrizations of $\gamma^1,\gamma^2$ introduced in \eqref{eq: reparametrization} and write $\bar \gamma^j = \gamma^j \circ g_j$, $j = 1,2$ for the reparametrized curves. Let $s,t \in [0,4]$ such that $\bar \gamma_s \leq \bar \gamma_t$. If $s > t$, suppose in addition that $\bar \gamma^1_{s-t} \leq \bar \gamma^2_0$. Then
\begin{equation}
    \ell(\bar \gamma^1_s,\bar \gamma^2_t)^2 \geq \ell(\gamma_0^1, \gamma_0^2)^2 + (t-s)^2 + 2(t-s)(F(\gamma_0^2)- F(\gamma_0^1)) + \Psi (\delta, L) \, .
\end{equation}

We argue the case $s \leq t$, the argument for $s > t$ (under the additional assumption $\bar \gamma_{s-t} \leq \bar \gamma_t)$ is analogous. We make use of the compactly rewritten {asynchronous} expansion rate estimate given in Corollary \ref{Cor: Compact rewriting of second expansion estimates}. Thus,
    \begin{align*}
        \ell(\bar\gamma^1_s,\bar \gamma^2_t)^2 = \ell(\gamma^1_{g_1(s)},\gamma^2_{g_2(t)})^2 &\geq e^{2 \lambda \min(g_1(s),g_2(t))} \bigg(\ell(\gamma^1_0,\gamma^2_0)^2 + (g_2(t) - g_1(s))^2 (\mathrm{md}^{-\delta})'(F(\gamma^1_0))^2 \\
        &\quad + 2(g_2(t) - g_1(s)) (\mathrm{md}^{-\delta}(F(\gamma_0^2)) - \mathrm{md}^{-\delta}(F(\gamma_0^1))) \bigg).
    \end{align*}
    Then
    {\eqref{eq: bounds on g} yields}
    \begin{equation*}
        g_2(t) - g_1(s) \geq \log\left(1 + \frac{t+\Psi}{L + \tilde R} \right) - \log\left(1 + \frac{s+\Psi}{L + R}\right) = \frac{t}{L + \tilde R} - \frac{s}{L +R} + \frac{\Psi}{L},
    \end{equation*}
    where in the last estimate we used the Maclaurin expansion for $\log (1+x)$. Since {\eqref{eq: reparametrization} gives}
    \begin{equation*}
        (\mathrm{md}^{-\delta})'(F(\gamma_0^1))^2 \geq (\mathrm{md}^{-\delta})'(L +\tilde R)^2 = (L + \tilde R)^2 + \Psi,
    \end{equation*}
    we have that
    \begin{align*}
        (g_2(t) - g_1(s))^2 (\mathrm{md}^{-\delta})'(F(\gamma_0^1))^2 &\geq \bigg( \frac{t}{L + \tilde R} - \frac{s}{L + R} + \frac{\Psi}{L}\bigg)^2 ((L + \tilde R)^2 + \Psi)\\
        &= \bigg(\left(\frac{t}{L + \tilde R} - \frac{s}{L +R}\right)^2 + \frac{\Psi}{L^2}\bigg) ((L+\tilde R)^2 + \Psi)\\
        &= (t -s)^2 + \Psi.
    \end{align*}
    The mixed term can be estimated in a similar way. Finally, noticing that $e^{2 \lambda \min(g_1(s),g_2(t))} = 1 + \Psi$ concludes the proof.

Given the timelike maximizer $\Upsilon:[-L,L] \to \mathcal M$, we use $F$ and $G$ from \eqref{F and G} to define the \emph{approximate Busemann functions} $b_L^\pm: J(\Upsilon_{-L},\Upsilon_L) \to \mathbb R$ associated with $\Upsilon$ via
\begin{align}
\label{b^+_L}
    &b^+_L(x):=L - \ell(\Upsilon_{-L},x) =: L - F(x),\\
    &b_L^-(x):= L - \ell(x, \Upsilon_L) =: L - G(x).
\label{b^-_L}
\end{align}

\label{Prop: Estimate on Busemann sum}
On $J:=J(\Upsilon_{-20},\Upsilon_{20})$, we have that
\begin{equation}
    0 \leq b^+_L + b^-_L \leq \Psi(\delta,L).
\end{equation}
Moreover, there exists a constant $C > 0$ independent of $L$ and $\delta$ such that
\begin{equation}
    -C \leq L^2 - \frac{F^2}{2} - \frac{G^2}{2} \leq C \qquad \text{on $J$} .
\end{equation}

We restrict ourselves to showing this inequality in the interior $I := I(\Upsilon_{-20},\Upsilon_{20})$ of $J$. The claim for $J$ then follows by continuity. Pick $x \in I$ and let $\sigma:[0,1] \to \mathcal M$ be a maximizing timelike geodesic parametrized proportional to $g$-arclength connecting $\Upsilon_{-20}$ to $x$. By causal $\lambda$-convexity of $F_\delta:=\mathrm{md}^{-\delta} \circ F$ and $G_\delta:=\mathrm{md}^{-\delta} \circ G$ on $I(\Upsilon_{-20},\Upsilon_{20})$, we have that 
    \begin{align}
        F_\delta(x) &\geq F_\delta (\Upsilon_{-20}) + \frac{d}{dt}\bigg|_{t=0} F_\delta(\sigma_t) + \frac{\lambda}{2} \ell(\Upsilon_{-20},x)^2 \nonumber \\
        &= \mathrm{md}^{-\delta}(L - 20) + (\mathrm{md}^{-\delta})'(L - 20) \langle \Upsilon_{-20}', \sigma'_0\rangle  + \frac{\lambda}{2} \ell(\Upsilon_{-20}, x)^2. \label{eq: F_delta expansion}
    \end{align}
    Analogously,
    \begin{align}
    \label{eq: G_delta expansion}
        G_\delta(x) \geq \mathrm{md}^{-\delta}(L + 20) - (\mathrm{md}^{-\delta})'(L + 20) \langle \Upsilon_{-20}',\sigma_0'\rangle + \frac{\lambda}{2} \ell(\Upsilon_{-20}, x)^2.
    \end{align}
    Let us define the quantities $A:=\langle \Upsilon'_{-20},\sigma_0'\rangle$ and $B:=\ell(\Upsilon_{-20},x)^2$. Convexity and the fact that $F(x) \leq L + 20$ imply
    \begin{equation*}
        0 \leq A \leq \frac{\mathrm{md}^{-\delta}(L+20) - \mathrm{md}^{-\delta}(L-20)}{(\mathrm{md}^{-\delta})'(L-20)} \leq 40 \frac{(\mathrm{md}^{-\delta})'(L+20)}{(\mathrm{md}^{-\delta})'(L-20)} \leq 80,
    \end{equation*}
    where the last inequality holds for sufficiently large $L$. Moreover, by the reverse triangle inequality,
    \begin{equation*}
        0 \leq B = \ell(\Upsilon_{-20},x)^2 \leq \ell(\Upsilon_{-20},\Upsilon_{20})^2 = 1600.
    \end{equation*}
    Observe that the bounds on $A$ and $B$ do not depend on $L$ or $\delta$. Expanding \eqref{md} for small $\delta$ shows that $F_\delta = \frac{F^2}{2} + \Psi$, and similarly $G_\delta = \frac{G^2}{2} + \Psi$. It follows (by similarly expanding the right hand sides in \eqref{eq: F_delta expansion} and \eqref{eq: G_delta expansion}) that 
    \begin{align}
        \frac{F(x)^2}{2} &\geq \frac{(L - 20)^2}{2} + (L-20)\langle \Upsilon_{-20}',\sigma_0'\rangle + \frac{\lambda}{2}  \ell(\Upsilon_{-20},x)^2 + \Psi, \label{eq: estimate from below for F}\\
        \frac{G(x)^2}{2} &\geq \frac{(L + 20)^2}{2} - (L+20)\langle \Upsilon_{-20}',\sigma_0'\rangle + \frac{\lambda}{2}  \ell(\Upsilon_{-20},x)^2 + \Psi. \label{eq: estimate from below for G}
    \end{align}
    Upon taking square roots, we obtain
    \begin{align}
        &F(x) \geq \sqrt{(L - 20)^2 + 2(L - 20)A + \lambda B} + \Psi(\delta, L),\\
       &G(x) \geq \sqrt{(L + 20)^2 - 2(L + 20)A + \lambda B} + \Psi(\delta,L).
   \end{align}
    We conclude that
    \begin{align*}
        0 &\leq b_L^-(x) + b_L^+(x) 
        \\&= 2L - F(x) - G(x)\\
        &\leq 2L - \sqrt{(L - 20)^2 + 2(L - 20)A + \lambda B} 
        - \sqrt{(L + 20)^2 - 2(L + 20)A + \lambda B}
         + \Psi(\delta, L)\\
        &= \Psi(\delta,L).
    \end{align*}
    To obtain the additional claim, we sum \eqref{eq: estimate from below for F} and \eqref{eq: estimate from below for G} and simplify:
    \begin{align*}
        L^2 - \frac{F(x)^2}{2} - \frac{G(x)^2}{2} &\leq L^2 -  \frac{(L - 20)^2}{2} - (L-20)A - \lambda  B
        - \frac{(L + 20)^2}{2} + (L+20)A
        + \Psi\\ &\leq C.
    \end{align*}
    For the lower bound, notice that {$F,G \in [L-20,L+20]$ on $J(\Upsilon_{-20},\Upsilon_{20})$. Hence $|F-G|\le 40$ while} $2L \geq F + G$ by the reverse triangle inequality. Thus
    \begin{align*}
        L^2 - \frac{F^2}{2} - \frac{G^2}{2} {=} \underbrace{\bigg( L - \frac{F + G}{2} \bigg)}_{\geq 0} \bigg(L + \frac{F + G}{2}\bigg) - \frac{1}{4} (F - G)^2 \geq -C.
    \end{align*}

\label{Proposition: Almost linearity}
For every $x \in I(\Upsilon_{-10},\Upsilon_{10})$ and $t \in [0,4]$, the {(reparametrized)} flow $\bar \gamma_t$ of $F$ \eqref{F and G} starting at $x$ satisfies
\begin{equation}
{ 0  \leq F(\bar \gamma_t) - F(x) -t \leq \Psi(\delta,L). }
\label{linearity}
\end{equation}

\label{Prop: almost pythagoras flow formula}
Let $x,y \in J(\Upsilon_{-1},\Upsilon_1)$ such that $x \leq y$ and let $s,t \in [0,2]$ be such that $\text{\rm Fl}^+_s(x) \leq \text{\rm Fl}^+_t(y)$. Then
\begin{equation}\label{future Pythagoras}
\ell(\text{\rm Fl}^+_s(x),\text{\rm Fl}^+_t(y))^2 = \ell(x,y)^2 + (t-s)^2 + 2(t-s) (F(y) - F(x)) + \Psi(\delta,L).
\end{equation}
If instead $x \geq y$ and $s,t \in [0,2]$ such that $\text{\rm Fl}^-_s(x) \geq \text{\rm Fl}^-_t(y)$, then
\begin{equation}\label{past Pythagoras}
    \ell(\text{\rm Fl}^-_t(y),\text{\rm Fl}^-_s(x))^2 = \ell(y,x)^2 + (t-s)^2 + 2(t-s) (G(y) - G(x)) + \Psi(\delta,L).
\end{equation}

We obtain the formula involving $\text{\rm Fl}^+$ below. The derivation of the formula involving $\text{\rm Fl}^-$ is analogous. In Steps 1 and 2, we prove the assertions for initial points
$x,y\in J(\Upsilon_{-4},\Upsilon_4)$, with the same time bounds
and causal assumptions. This permits their application to the
flowed points occurring in Step 3.

    \begin{enumerate}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} \textbf{STEP 1: $t = 0$.} The inequality $\geq$ is a consequence of Proposition \ref{Prop: second estimate for reparametrized flow}. Consider now $[0,4] \ni t \mapsto \text{\rm Fl}^-_t(\text{\rm Fl}^+_s(x))$. Using the time-reversed one-sided case of Proposition \ref{Prop: second estimate for reparametrized flow} for $\ell(\text{\rm Fl}^-_t(\text{\rm Fl}^+_s(x)),y)^2$, in conjunction with the above noted inequality $\geq$ in our claim,
        we obtain
        \begin{align*}
            \ell(\text{\rm Fl}^-_t(\text{\rm Fl}^+_s(x)),y)^2 &\geq \ell(\text{\rm Fl}^+_s(x),y)^2 + t^2 + 2t(G(\text{\rm Fl}^+_s(x)) - G(y)) + \Psi\\
            &\geq \ell(x,y)^2 + s^2 - 2s(F(y) - F(x)) 
            + t^2 + 2t(G(\text{\rm Fl}^+_s(x)) - G(y)) + \Psi.
        \end{align*}
        From $F = {2L -}G + \Psi$ (Proposition \ref{Prop: Estimate on Busemann sum}) as well as the almost linearity provided by Proposition \ref{Proposition: Almost linearity},
        we continue estimating 
        \begin{align}\nonumber
            \ell(\text{\rm Fl}^-_t(\text{\rm Fl}^+_s(x)),y)^2 &\geq \ell(x,y)^2 + s^2 -2s(F(y) - F(x)) 
            +t^2 +2t(-F(x) - s + F(y)) + \Psi\\
            &= \ell(x,y)^2 + (t-s)^2 + 2(t-s)(F(y) - F(x)) + \Psi.
        \label{3.41bis}\end{align}
        Similarly, we may estimate for $t > 0$ and $x \leq \text{\rm Fl}^-_t(\text{\rm Fl}^+_s(x))$ that
        \begin{align}
            \ell(x,\text{\rm Fl}^-_t(\text{\rm Fl}^+_s(x)))^2 \geq (t-s)^2 + \Psi. \label{eq3.41}
        \end{align}
        The case $s=0$ is immediate, so suppose $s>0$ and put
$q:=\text{\rm Fl}^+_s(x)$. By $1$-steepness of $F$ and the
lower bound $1$ for the Lorentzian speed of the past flow,
\begin{equation*}
F(\text{\rm Fl}^-_r(q))\le F(q)-r.
\end{equation*}
Consequently, this curve cannot remain in $I^+(x)$ beyond
$r=F(q)-F(x)=s+\Psi<3$. Since $q\in J(x,y)$, its existence
up to this time follows from Lemma \ref{Lemma: Almost monotonicity of reparam grad flow}. Thus there is a unique
first contact time $\bar t\in[0,3]$ such that
$\text{\rm Fl}^-_{\bar t}(q)\in\partial J^+(x)$ and
$\ell(x,\text{\rm Fl}^-_{\bar t}(q))=0$.
From the above estimate \eqref{eq3.41}, we obtain that
        \begin{align*}
            0 \geq (\bar t - s)^2 + \Psi \geq \Psi
        \end{align*}
        Subtracting $\Psi$ from both sides and taking the square root we get
        \begin{align*}
            \bar t = s + \Psi.
        \end{align*}
        Thus, the reverse triangle inequality in conjunction with our estimate \eqref{3.41bis} produces
        \begin{align*}
            \ell(x,y)^2 &\geq  (\underbrace{\ell(x,\text{\rm Fl}^-_{\bar t}(\text{\rm Fl}^+_s(x)))}_{=0} + \ell(\text{\rm Fl}^-_{\bar t}(\text{\rm Fl}^+_s(x)), y))^2 \\
            &\geq \ell(x,y)^2 + (\bar t -s)^2 + 2(\bar t - s) (F(y) - F(x)) + \Psi.
        \end{align*}
        Given that $\bar t=s+\Psi$ and $|F(y)-F(x)|\le8$,
the right-hand side is $\ell(x,y)^2+\Psi$. Thus, all of the inequalities have to be equalities, so that in particular
        \begin{align*}
        \ell(\text{\rm Fl}^+_s(x),y)^2 = \ell(x,y)^2 + s^2 - 2s(F(y) - F(x)) + \Psi.
        \end{align*}
        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} \textbf{STEP 2: $s = 0$.} Let $y_r:=\mathrm{Fl}^+_r(y)$, and first assume $x\ll y$.
By Lemma \ref{Lemma: Almost monotonicity of reparam grad flow}, the points under consideration lie in
$I(\Upsilon_{-15},\Upsilon_{15})$.
During the course of this step only, we write
\begin{equation*}
 U:=\operatorname{md}^{-\delta}\circ F,
 \qquad
 V:=\operatorname{md}^{-\delta}\circ G,
 \qquad
 D(q):=(\operatorname{md}^{-\delta})'(F(q)).
\end{equation*}
By Proposition \ref{Prop: Estimate on Busemann sum},
\begin{equation*}
 |U+V-L^2|\leq C_0
 \quad\text{on }J(\Upsilon_{-20},\Upsilon_{20}),
\end{equation*}
where $C_0$ is independent of $\delta,L$, and
\begin{equation*}
 U=\frac{F^2}{2}+\Psi,\qquad
 V=\frac{G^2}{2}+\Psi,\qquad
 D=F+\Psi,\qquad F+G=2L+\Psi.
\end{equation*}
We first establish an endpoint estimate.
Fix $x\ll q$ in $I(\Upsilon_{-15},\Upsilon_{15})$ and an
affinely parametrized maximizing timelike geodesic
$\sigma:[0,1]\to M$ from $x$ to $q$.
We claim that its (not necessarily maximizing) geodesic extension is defined on $[0,1+h]$, where
$h:=1/1000$, and remains in
$I(\Upsilon_{-20},\Upsilon_{20})$. This is shown via a convexity argument, cf.\ the proof of Proposition \ref{Proposition: Almost linearity}.

Put $w:=\dot\sigma_1$ and $z:=\sigma_{1+h}$, and suppose $u \in T_q \mathcal M$ satisfies
$D(q)u^\flat\in\partial_{\le}U(q)$ (this will subsequently be applied to $u = \dot y_r$).
Testing the causal subdifferential inequality with $-w$ and $hw$
gives
\begin{equation*}
 U(q)-U(x)
 \le D(q) \mathsf g(u,w)
 \le\frac{U(z)-U(q)}h.
\end{equation*}
Convexity of $V\circ\sigma$ gives
\begin{equation*}
 V(z)-V(q)\ge h\bigl(V(q)-V(x)\bigr).
\end{equation*}
Together with the bound on $U+V$, these inequalities imply
\begin{equation*}
 \frac{U(q)-U(x)}{D(q)}
 \le \mathsf g(u,w)
 \le
 \frac{V(x)-V(q)}{D(q)}+\frac{2C_0}{hD(q)}.
\end{equation*}
Since $F,G\in[L-15,L+15]$ at $x,q$, the preceding
asymptotic estimates yield
\begin{equation*}
 \frac{U(q)-U(x)}{D(q)}=F(q)-F(x)+\Psi,
 \qquad
 \frac{V(x)-V(q)}{D(q)}=F(q)-F(x)+\Psi.
\end{equation*}
Moreover, $2C_0/(hD(q))=O(L^{-1})=\Psi$.
We have therefore proved that
\begin{equation*}
 \mathsf g(u,\dot\sigma_1)=F(q)-F(x)+\Psi.
\end{equation*}
For almost every $r\in(0,t)$, $y_r$ is differentiable
and satisfies
\begin{equation*}
 D(y_r)\dot y_r^\flat\in\partial_{\le}U(y_r).
\end{equation*}
Fix such an $r$, and let $\sigma:[0,1]\to M$ be an affinely
parametrized maximizing geodesic from $x$ to $y_r$.
Lemma \ref{L:gradient estimate} gives
\begin{equation*}
 \left.\frac{d^+}{ds}\right|_{s=r}
 \frac{\ell(x,y_s)^2}{2}
 \ge \mathsf g(\dot y_r,\dot\sigma_1).
\end{equation*}
For the corresponding left Dini derivative, choose $\rho<1$
sufficiently close to $1$ so that
$p\mapsto\ell(\sigma_\rho,p)$ is smooth near $y_r$.
For sufficiently small $\varepsilon>0$, the reverse triangle
inequality gives
\begin{equation*}
 \ell(x,y_{r-\varepsilon})
 \ge
 \ell(x,\sigma_\rho)+\ell(\sigma_\rho,y_{r-\varepsilon}),
\end{equation*}
whereas maximality of $\sigma$ gives
\begin{equation*}
 \ell(x,y_r)
 =
 \ell(x,\sigma_\rho)+\ell(\sigma_\rho,y_r).
\end{equation*}
Squaring, subtracting the former inequality from the latter
equality, and dividing by $2\varepsilon$, the usual first
variation formula yields
\begin{equation*}
 \left.\frac{d^-}{ds}\right|_{s=r}
 \frac{\ell(x,y_s)^2}{2}
 \le \mathsf g(\dot y_r,\dot\sigma_1).
\end{equation*}
Since $x\ll y$, the function
$r\mapsto\ell(x,y_r)^2/2$ is locally Lipschitz.
Consequently, for almost every $r$, its left and right Dini derivatives both agree with its ordinary derivative.
From the inequalities established above and
Proposition \ref{Proposition: Almost linearity} we can thus conclude that
\begin{equation*}
 \frac{d}{dr}\frac{\ell(x,y_r)^2}{2}
 =
 g(\dot y_r,\dot\sigma_1)
 =
 F(y_r)-F(x)+\Psi
 =
 F(y)-F(x)+r+\Psi
\end{equation*}
for almost every $r\in(0,t)$. Integrating from $0$ to $t$, we get
\begin{equation*}
 \ell(x,\mathrm{Fl}^+_t(y))^2
 =
 \ell(x,y)^2+t^2+2t\bigl(F(y)-F(x)\bigr)+\Psi.
\end{equation*}
The case $x\leq y$ but $x \not \ll y$ is argued by approximation.

        \refstepcounter{inlineenum}{(\roman{inlineenum})\hspace{\thelabelsep}} \textbf{STEP 3: General case.} If both $s, t \neq 0$, then one can simply proceed in two steps using steps 1 and 2 as follows:
        \begin{align*}
            \ell(\text{\rm Fl}^+_s(x),\text{\rm Fl}^+_t(y))^2 &= \ell(x,\text{\rm Fl}^+_t(y))^2 + s^2 - 2s(\underbrace{F(\text{\rm Fl}^+_t(y))}_{= F(y) + t + \Psi} - F(x)) + \Psi\\
            &= \ell(x,y)^2 + t^2 + s^2 - 2s(F(y) + t  - F(x)) + 2t(F(y) - F(x)) + \Psi\\
            &= \ell(x,y)^2 + (t-s)^2 + 2(t-s)(F(y) - F(x)) + \Psi.
        \end{align*}
    \end{enumerate}

\label{Prop: flow metrization}
Let $X:=J(\Upsilon_{-1},\Upsilon_1) \cap \{b_L^+ = 0\}$ with $b_L^+$ from \eqref{b^+_L} and for $x,y \in X$ define
\begin{equation}
\label{eq: def tilde d}
    \tilde {\mathsf{d}}(x,y):= \min\{t \in [0,4] : \text{\rm Fl}^+_t(x) \geq y \text{ and } \text{\rm Fl}^+_t(y) \geq x\}.
\end{equation}
Then there exists $0 \leq \theta \leq  \Psi$ such that the {infimum} in the definition of $\tilde {\mathsf{d}}$ can be taken on $[0,2+\theta]$. Moreover, defining $\mathsf d:=\tilde{\mathsf {d}} + \theta$ on $X^2 \setminus \{(x,x) : x \in X\}$ and $\mathsf{d}(x,x):=\tilde{\mathsf{d}}(x,x) = 0$, the pair $(X,\mathsf{d})$ is a metric space. Finally, if $x,y \in X$, then
\begin{equation*}
    \ell(x,\text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(y)) = 0 \quad \text{or} \quad \ell(y,\text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)) = 0.
\end{equation*}

Fix $x,y \in X$. Since $y \in J(\Upsilon_{-1},\Upsilon_1)$, by Lemma \ref{Lemma: Almost monotonicity of reparam grad flow}, $\text{\rm Fl}^+_t(y) \in J(\Upsilon_{-1 + t + \Psi}, \Upsilon_{1 + t + \Psi})$. By a continuity argument we may obtain a $\theta \geq 0$ of type $\Psi$ such that, if $t \geq 2 + \theta$, then $\text{\rm Fl}^+_t(y) \geq x$ as well as $\text{\rm Fl}^+_t(x) \geq y$.

    Let us show that $\mathsf d$ is a metric on $X$. Clearly, $\tilde {\mathsf{d}}(x,x) = \mathsf{d}(x,x) = 0$. Symmetry of $\tilde {\mathsf{d}}$ (and thus of $\mathsf{d}$) follows from the definition. It remains to argue the triangle inequality for $\mathsf{d}$, for which it is sufficient to show that the triangle inequality holds for $\tilde{\mathsf{d}}$ up to an addition of $\theta$. To this end, let $x,y,z \in X$, define $T:= \tilde{\mathsf{d}}(x,y)$, $S:=\tilde{\mathsf{d}}(y,z)$. By definition,
    \begin{equation*}
        \text{\rm Fl}^+_T(x) \geq y, \, \text{\rm Fl}^+_T(y) \geq x, \, \text{\rm Fl}^+_S(z) \geq y, \, \text{\rm Fl}^+_S(y) \geq z.
    \end{equation*}
    For sufficiently large $\xi$, certainly $\text{\rm Fl}^+_{S+ \xi}(z) \geq \text{\rm Fl}^+_T(y)$. Using Proposition \ref{Prop: second estimate for reparametrized flow}, after a fixed rescaling if necessary,
and noting that $F(z)=L=F(y)$, we obtain  
    \begin{align*}
        \ell(\text{\rm Fl}^+_{T}(y),\text{\rm Fl}^+_{S + \xi}(z))^2 &\geq \underbrace{\ell(y,\text{\rm Fl}^+_S(z))^2}_{ \ge 0} + (\xi - T)^2 + 2(\xi - T)(\underbrace{F(\text{\rm Fl}^+_S(z))}_{=S + \Psi} - F(y)) + \Psi \\
        &{\ge} (\xi - T)^2 + 2(\xi - T)S + \Psi.
    \end{align*}
    Let $\xi_0$ be the first nonnegative parameter for which
$\text{\rm Fl}^+_{S+\xi_0}(z)\ge\text{\rm Fl}^+_T(y)$.
If $\xi_0>T+\theta$, the left-hand side of the above estimate
vanishes at $\xi_0$, whereas its right-hand side is strictly
positive after increasing $\theta$ within the class $\Psi$,
a contradiction. Thus $\xi_0\leq T+\theta$, hence
$x\leq\text{\rm Fl}^+_T(y)\leq\text{\rm Fl}^+_{T+S+\theta}(z)$. Analogously, $z \leq \text{\rm Fl}^+_{T + S + \theta} (x)$. Thus,
    \begin{equation*}
        \tilde{\mathsf{d}}(x,z) \leq T + S + \theta = \tilde{\mathsf{d}}(x,y) + \tilde{\mathsf{d}}(y,z) + \theta.
    \end{equation*}
    To show the final claim, let $T:=\tilde{\mathsf{d}}(x,y)$ and suppose that 
    \begin{equation*}
        \ell(x,\text{\rm Fl}^+_T(y)) > 0 \quad \text{and} \quad \ell(y,\text{\rm Fl}^+_T(x)) > 0.
    \end{equation*}
    By continuity, there is $\varepsilon > 0$ such that $x \leq \text{\rm Fl}^+_{T - \varepsilon}(y)$ and $y \leq \text{\rm Fl}^+_{T - \varepsilon}(x)$, which would imply $T\leq T-\varepsilon$, a contradiction.

\label{P:almost symmetry}
Let $x,y \in X$ and suppose that $\ell(x,\emph{\text{\rm Fl}}^+_{\tilde{\mathsf{d}}(x,y)} (y)) =  0$, then
\begin{equation}
    0 \leq \ell(y,\emph{\text{\rm Fl}}^+_{\tilde{\mathsf{d}}(x,y)}(x)) = \Psi.
\end{equation}
In particular, also $\ell(y,\text{\rm Fl}^+_{\mathsf{d}(x,y)}(x)) =\Psi$.

By the first-contact argument in Proposition \ref{Prop: flow metrization} and the almost-Pythagoras formula \eqref{future Pythagoras}, we have that
    \[
    0 < \ell(\text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)} (x),\text{\rm Fl}^+_{2\tilde{\mathsf{d}}(x,y) + \Psi}(y)) = \Psi \, .
    \]
    We may assume that $0 < \ell(y,\text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x))$, otherwise there is nothing to show.  Notice that, since $F(x) = L$ (equivalently, $b^+_L(x) = 0$), by almost linearity of $F$ along $\text{\rm Fl}^+$ we have that $F( \text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)) = F(x) + \tilde{\mathsf{d}}(x,y) + \Psi = L + \tilde{\mathsf{d}}(x,y) + \Psi$.
    Choose $K=K(\delta,L)\to\infty$ sufficiently slowly so that
$K = o(L)$ and
\begin{equation*}
K^2\Psi(\delta K^2,L/K)\longrightarrow0,
\end{equation*}
where $\Psi$ denotes the error in \eqref{future Pythagoras}. Connect $\Upsilon_{-K}$ to $\text{\rm Fl}^+_{2\tilde{\mathsf{d}}(x,y) + \Psi}(y)$ via a maximizing future directed $\mathsf g$-arclength parametrized timelike geodesic $\sigma:[0,S] \to M$, where $S:=\ell(\Upsilon_{-K},\text{\rm Fl}^+_{2\tilde{\mathsf{d}}(x,y) + \Psi}(y))$. Note that $\sigma$ intersects $\partial J^-(y)$ uniquely at a point $z$, and since $y \ll \text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)$ by assumption, we have $z \ll \text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)$. Now consider the timelike triangle $\Delta(\Upsilon_{-K},\text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x), \text{\rm Fl}^+_{2\tilde{\mathsf{d}}(x,y) + \Psi}(y))$. By triangle comparison,
    \begin{equation}
        0 < \ell(z, \text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)) \leq \bar \ell_{-\delta}(\bar z, \bar x_{\tilde{\mathsf{d}}}),
    \end{equation}
    where $\bar x_{\tilde{\mathsf{d}}}$ is the point corresponding to $\text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)$ on the comparison triangle in $\mathbb{L}^2(-\delta)$. 
    Set $F_K:=\ell(\Upsilon_{-K},\cdot)$ and
$G_K:=\ell(\cdot,\Upsilon_K)$. Proposition \ref{Prop: Estimate on Busemann sum} applied to
$\Upsilon|_{[-K,K]}$, together with the reverse triangle
inequality, gives on $J(\Upsilon_{-20},\Upsilon_{20})$
\begin{equation*}
0\le F-(L-K+F_K)\le2K-F_K-G_K\le\Psi(\delta,K).
\end{equation*}
In particular,
    \begin{equation} \label{eq: hinge}
        F( \xi) = F \left (\Upsilon_{-K} \right ) + \ell ( \Upsilon_{-K}, \xi) + \Psi \, .
    \end{equation}
    Consider the rescaled metric $\mathsf g'=K^{-2}\mathsf g$. Its curvature parameter is $\delta K^2$ and the rescaled half-length of $\Upsilon$ is $L/K$. Since
$\Upsilon_{-K}\le z\le y\le\Upsilon_K$, we may apply \eqref{future Pythagoras}
to $z,y$ in the rescaled metric. Rescaling back, its error
is $K^2\Psi(\delta K^2,L/K)=\Psi$, and we obtain
    \begin{align} \label{eq: quadr}
        \ell(z, \text{\rm Fl}^+_{2\tilde{\mathsf{d}}(x,y) + \Psi}(y))^2 &= (2\tilde{\mathsf{d}}(x,y) + \Psi)^2 + 2(2\tilde{\mathsf{d}}(x,y) + \Psi)(L-F(z)) + \Psi \, .
    \end{align}
    Put $T:=2\tilde{\mathsf d}(x,y)+\Psi$,
$p:=\text{\rm Fl}^+_T(y)$ and $c:=\ell(z,p)$.
Since $z$ lies on the maximizing geodesic from
$\Upsilon_{-K}$ to $p$, the reverse triangle inequality
and \eqref{eq: hinge} at $p$ give
\begin{equation*}
0\le F(p)-F(z)-c
\le F(p)-(L-K+F_K(p))=\Psi.
\end{equation*}
Thus $F(z)+c=L+T+\Psi$, and \eqref{eq: quadr} gives
$(c-T)^2=\Psi$, which establishes that
    \begin{equation*}
        0 < \ell(z, \text{\rm Fl}^+_{2\tilde{\mathsf{d}}(x,y) + \Psi}(y)) = 2\tilde{\mathsf{d}}(x,y) + \Psi.
    \end{equation*}
    We now apply the law of cosines to the comparison triangle
of
\begin{equation*}
\Delta\bigl(\Upsilon_{-K},
\text{\rm Fl}^+_{\tilde{\mathsf d}(x,y)}(x),p\bigr),
\end{equation*}
where $\bar z$ lies on the side corresponding to the
maximizer from $\Upsilon_{-K}$ to $p$.
The preceding estimates give
\begin{align*}
\ell(\Upsilon_{-K},z)&=K+\Psi,\\
\ell(z,p)&=2\tilde{\mathsf d}(x,y)+\Psi,\\
\ell(\Upsilon_{-K},
\text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x))
&=K+\tilde {\mathsf{d}}(x,y)+\Psi,\\
\ell(\text{\rm Fl}^+_{\tilde{\mathsf  d}(x,y)}(x),p)&=\Psi.
\end{align*}
Thus the asymptotic formula in the law of cosines, whose remainder is
$O(\delta K^4)=\Psi$, yields
    \begin{align*}
        \ell_{-\delta}(\bar z, \bar x_{\tilde{\mathsf{d}}})^2 = \frac{(K +\tilde{\mathsf{d}}(x,y) + \Psi)^2(2\tilde{\mathsf{d}}(x,y) + \Psi) + \Psi^2 (K + \Psi)}{K + 2\tilde{\mathsf{d}}(x,y) + \Psi} - (K+\Psi)(2 \tilde{\mathsf{d}}(x,y) + \Psi) + \Psi.
    \end{align*}
    Upon bringing the terms to the same denominator, it is easily checked that $\bar \ell_{-\delta}(\bar z, \bar x_{\tilde{\mathsf{d}}}) = \Psi$, which on the other hand lets us conclude that
    \begin{align*}
        0 < \ell(z, \text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)) = \Psi.
    \end{align*}
    Observing that $\ell(z, \text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)) \geq \ell(y, \text{\rm Fl}^+_{\tilde{\mathsf{d}}(x,y)}(x)) > 0$ by the reverse triangle inequality concludes the proof.

\label{Remark: flows are inverse}
In Proposition \ref{Prop: almost pythagoras flow formula}, we obtain as a consequence of its proof that if $x \in J(\Upsilon_{-1},\Upsilon_1)$ and $s \in [0,2]$, then there exists a unique $\bar t = s + \Psi$ such that $\text{\rm Fl}^-_{\bar t}(\text{\rm Fl}^+_s(x)) \in \partial J^+(x)$, and similarly with $\text{\rm Fl}^+$ and $\text{\rm Fl}^-$ interchanged.
Also note that if $y\in J(\Upsilon_{-1},\Upsilon_1)$, then
\begin{equation*}
\ell_+(x,y)
=\ell_+\bigl(\text{\rm Fl}^-_{\bar t}
(\text{\rm Fl}^+_s(x)),y\bigr)+\Psi.
\end{equation*}
This follows from \eqref{future Pythagoras}-\eqref{past Pythagoras}, first flowing $y$ a fixed
amount to the future and then comparing the resulting
formulas up to the first causal contact.

\label{Corollary: mixed flows}
    Let $x,y \in J(\Upsilon_{-1},\Upsilon_1)$ and $s,t \in [0,2]$ be such that $\text{\rm Fl}^-_s(x) \leq \text{\rm Fl}^+_t(y)$. Then
    \begin{equation}\label{mixed Pythagoras}
        \ell(\text{\rm Fl}^-_s(x),\text{\rm Fl}^+_t(y))^2 = \ell_+(x,y)^2+(t+s-d)^2
+2(t+s-d)(b_L^+(x)-b_L^+(y)+d)+\Psi
    \end{equation}
    where $d \geq 0$ is the minimal time such that $\text{\rm Fl}^+_d(y) \geq x$. 
    In particular, if $x,y \in X$, then
    \begin{equation}
    \label{eq: pythagoras from slice}
        \ell(\text{\rm Fl}^-_s(x),\text{\rm Fl}^+_t(y))^2 = (t+s)^2 - \mathsf{d}(x,y)^2 + \Psi.
    \end{equation}
